  1→/**
  2→ * Public API endpoint — joins a customer to the waitlist from the storefront widget.
  3→ *
  4→ * Called from the theme app extension block when a zip code check fails and
  5→ * the merchant has enabled the waitlist feature.
  6→ *
  7→ * POST /api/waitlist
  8→ * Body: { shop: string, zip: string, email: string }
  9→ *
 10→ * Response:
 11→ *   200 { success: true, message: "..." }
 12→ *   400 { error: "..." }
 13→ *   500 { error: "..." }
 14→ */
 15→import type { ActionFunctionArgs, LoaderFunctionArgs } from "react-router";
 16→import db from "../db.server";
 17→import { getShopSubscription } from "../billing.server";
 18→import { UNLIMITED } from "../plans";
 19→import { normalizeZipCode } from "../utils/zip";
 20→
 21→const CORS_HEADERS = {
 22→  "Access-Control-Allow-Origin": "*",
 23→  "Access-Control-Allow-Methods": "POST, OPTIONS",
 24→  "Access-Control-Allow-Headers": "Content-Type",
 25→  "Content-Type": "application/json",
 26→};
 27→
 28→// Handle CORS preflight
 29→export const loader = async ({ request }: LoaderFunctionArgs) => {
 30→  if (request.method === "OPTIONS") {
 31→    return new Response(null, { status: 204, headers: CORS_HEADERS });
 32→  }
 33→  return new Response(JSON.stringify({ error: "Method not allowed" }), {
 34→    status: 405,
 35→    headers: CORS_HEADERS,
 36→  });
 37→};
 38→
 39→export const action = async ({ request }: ActionFunctionArgs) => {
 40→  if (request.method === "OPTIONS") {
 41→    return new Response(null, { status: 204, headers: CORS_HEADERS });
 42→  }
 43→
 44→  if (request.method !== "POST") {
 45→    return new Response(JSON.stringify({ error: "Method not allowed" }), {
 46→      status: 405,
 47→      headers: CORS_HEADERS,
 48→    });
 49→  }
 50→
 51→  let shop: string | null = null;
 52→  let zip: string | null = null;
 53→  let email: string | null = null;
 54→  let name: string | null = null;
 55→
 56→  try {
 57→    const body = await request.json();
 58→    shop = body?.shop ?? null;
 59→    zip = body?.zip ?? null;
 60→    email = body?.email ?? null;
 61→    name = body?.name ?? null;
 62→  } catch {
 63→    return new Response(JSON.stringify({ error: "Invalid JSON body" }), {
 64→      status: 400,
 65→      headers: CORS_HEADERS,
 66→    });
 67→  }
 68→
 69→  if (!shop || !zip || !email) {
 70→    return new Response(
 71→      JSON.stringify({ error: "Missing required fields: shop, zip, email" }),
 72→      { status: 400, headers: CORS_HEADERS },
 73→    );
 74→  }
 75→
 76→  // Validate shop is a real myshopify.com domain (prevents cross-shop enumeration)
 77→  if (!/^[a-zA-Z0-9][a-zA-Z0-9-]*\.myshopify\.com$/.test(shop) || shop.length > 100) {
 78→    return new Response(
 79→      JSON.stringify({ error: "Invalid shop parameter" }),
 80→      { status: 400, headers: CORS_HEADERS },
 81→    );
 82→  }
 83→
 84→  // Enforce input length limits to prevent abuse
 85→  if (zip.length > 20 || email.length > 254) {
 86→    return new Response(
 87→      JSON.stringify({ error: "Invalid input" }),
 88→      { status: 400, headers: CORS_HEADERS },
 89→    );
 90→  }
 91→
 92→  if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)) {
 93→    return new Response(
 94→      JSON.stringify({ error: "Invalid email address" }),
 95→      { status: 400, headers: CORS_HEADERS },
 96→    );
 97→  }
 98→
 99→  // Check if shop's plan allows waitlist
100→  try {
101→    const subscription = await getShopSubscription(shop);
102→    if (subscription.limits.maxWaitlist === 0) {
103→      return new Response(
104→        JSON.stringify({ error: "Waitlist is not available on this store's plan" }),
105→        { status: 400, headers: CORS_HEADERS },
106→      );
107→    }
108→    // Enforce entry limit for Starter plan
109→    if (subscription.limits.maxWaitlist < UNLIMITED) {
110→      const currentCount = await db.waitlistEntry.count({ where: { shop } });
111→      if (currentCount >= subscription.limits.maxWaitlist) {
112→        return new Response(
113→          JSON.stringify({ error: "Waitlist is currently full. Please try again later." }),
114→          { status: 400, headers: CORS_HEADERS },
115→        );
116→      }
117→    }
118→  } catch {
119→    // If subscription check fails, deny the request to prevent plan bypass
120→    return new Response(
121→      JSON.stringify({ error: "Unable to verify subscription. Please try again later." }),
122→      { status: 503, headers: CORS_HEADERS },
123→    );
124→  }
125→
126→  try {
127→    await db.waitlistEntry.upsert({
128→      where: {
129→        shop_email_zipCode: {
130→          shop,
131→          email,
132→          zipCode: normalizeZipCode(zip),
133→        },
134→      },
135→      create: {
136→        shop,
137→        email,
138→        name: name ? name.trim().substring(0, 100) : null,
139→        zipCode: normalizeZipCode(zip),
140→        status: "waiting",
141→      },
142→      update: {
143→        status: "waiting",
144→      },
145→    });
146→
147→    return new Response(
148→      JSON.stringify({
149→        success: true,
150→        message: "You've been added to the waitlist!",
151→      }),
152→      { status: 200, headers: CORS_HEADERS },
153→    );
154→  } catch {
155→    return new Response(
156→      JSON.stringify({ error: "Failed to join waitlist. Please try again." }),
157→      { status: 500, headers: CORS_HEADERS },
158→    );
159→  }
160→};
