 33→
 34→export const loader = async ({ request }: LoaderFunctionArgs) => {
 35→  const { session } = await authenticate.admin(request);
 36→  const shop = session.shop;
 37→
 38→  const [subscription, zipCount, shopSettings] = await Promise.all([
 39→    getShopSubscription(shop),
 40→    db.zipCode.count({ where: { shop } }),
 41→    db.shopSettings.findUnique({ where: { shop } }),
 42→  ]);
 43→
 44→  return {
 45→    subscription,
 46→    zipCount,
 47→    shop,
 48→    defaultBehavior: shopSettings?.defaultBehavior ?? "block",
 49→    notificationEmail: shopSettings?.notificationEmail ?? "",
 50→  };
 51→};
 52→
 53→// ---------------------------------------------------------------------------
 54→// Action
 55→// ---------------------------------------------------------------------------
 56→
 57→export const action = async ({ request }: ActionFunctionArgs) => {
 58→  const { session } = await authenticate.admin(request);
 59→  const shop = session.shop;
 60→
 61→  const formData = await request.formData();
 62→  const intent = formData.get("intent") as string;
 63→
 64→  try {
 65→    if (intent === "save-behavior") {
 66→      const defaultBehavior = formData.get("defaultBehavior") as string;
 67→      if (defaultBehavior !== "block" && defaultBehavior !== "allow") {
 68→        return { error: "Invalid value for defaultBehavior" };
 69→      }
 70→      await db.shopSettings.upsert({
 71→        where: { shop },
 72→        create: { shop, defaultBehavior },
 73→        update: { defaultBehavior },
 74→      });
 75→      return { success: true, intent };
 76→    }
 77→
 78→    if (intent === "save-notification") {
 79→      const notificationEmail =
 80→        (formData.get("notificationEmail") as string | null) ?? "";
 81→      await db.shopSettings.upsert({
 82→        where: { shop },
 83→        create: { shop, notificationEmail: notificationEmail || null },
 84→        update: { notificationEmail: notificationEmail || null },
 85→      });
 86→      return { success: true, intent };
 87→    }
 88→
 89→    return { error: "Unknown intent" };
 90→  } catch {
 91→    return { error: "Failed to save settings. Please try again." };
 92→  }
 93→};
